pitfalls.badSnippet:
-- Over-indexing every single column in the table
CREATE INDEX idx_all_1 ON users(name);
CREATE INDEX idx_all_2 ON users(email);
CREATE INDEX idx_all_3 ON users(created_at);

-- Indexing name when queries filter by email
CREATE INDEX idx_users_name ON users(name);
SELECT * FROM users WHERE email = 'target@example.com';

pitfalls.goodSnippet:
-- Match index columns to your application's query predicates
CREATE INDEX idx_users_email ON users(email);
SELECT * FROM users WHERE email = 'target@example.com';
